    "sup.bug3": { en:"Your device model and OS version (iOS or Android)", es:"El modelo de tu dispositivo y la versión del sistema (iOS o Android)", fr:"Le modèle de votre appareil et la version du système (iOS ou Android)", pt:"O modelo do seu aparelho e a versão do sistema (iOS ou Android)", ar:"طراز جهازك وإصدار نظام التشغيل (iOS أو أندرويد)", zh:"你的设备型号和系统版本（iOS 或 Android）", nl:"Je toestelmodel en OS-versie (iOS of Android)", de:"Dein Gerätemodell und die Betriebssystemversion (iOS oder Android)", hi:"आपके डिवाइस का मॉडल और OS वर्शन (iOS या Android)", bn:"আপনার ডিভাইসের মডেল ও OS সংস্করণ (iOS বা Android)", id:"Model perangkat dan versi OS Anda (iOS atau Android)", ur:"آپ کے ڈیوائس کا ماڈل اور OS ورژن (iOS یا Android)", tr:"Cihaz modelin ve işletim sistemi sürümü (iOS ya da Android)", it:"Il modello del tuo dispositivo e la versione del sistema (iOS o Android)", ja:"端末のモデルとOSのバージョン（iOSまたはAndroid）", ko:"기기 모델과 OS 버전(iOS 또는 Android)", ru:"Модель устройства и версия системы (iOS или Android)" },
    "sup.bug4": { en:"Screenshots if possible", es:"Capturas de pantalla si es posible", fr:"Des captures d’écran si possible", pt:"Capturas de tela, se possível", ar:"لقطات شاشة إن أمكن", zh:"如果方便，请附上截图", nl:"Screenshots als dat kan", de:"Screenshots, wenn möglich", hi:"हो सके तो स्क्रीनशॉट", bn:"সম্ভব হলে স্ক্রিনশট", id:"Tangkapan layar bila memungkinkan", ur:"اگر ممکن ہو تو اسکرین شاٹس", tr:"Mümkünse ekran görüntüleri", it:"Screenshot, se possibile", ja:"可能であればスクリーンショット", ko:"가능하면 스크린샷", ru:"Скриншоты, если возможно" },
    "sup.rtTitle": { en:"Response Time", es:"Tiempo de respuesta", fr:"Délai de réponse", pt:"Tempo de resposta", ar:"زمن الاستجابة", zh:"回复时间", nl:"Reactietijd", de:"Antwortzeit", hi:"जवाब का समय", bn:"উত্তরের সময়", id:"Waktu Respons", ur:"جواب کا وقت", tr:"Yanıt süresi", it:"Tempi di risposta", ja:"返信までの時間", ko:"답변 소요 시간", ru:"Время ответа" },
    "sup.rtBody": { en:"We typically respond to all support requests within 24–48 hours. Thank you for your patience!", es:"Normalmente respondemos a todas las solicitudes de soporte en 24–48 horas. ¡Gracias por tu paciencia!", fr:"Nous répondons généralement à toutes les demandes sous 24 à 48 heures. Merci de votre patience !", pt:"Normalmente respondemos a todos os pedidos de suporte em 24–48 horas. Obrigado pela paciência!", ar:"نردّ عادةً على كل طلبات الدعم في خلال 24 إلى 48 ساعة. شكرًا لصبرك!", zh:"我们通常在 24–48 小时内回复所有支持请求。感谢你的耐心！", nl:"We reageren normaal gesproken binnen 24–48 uur op alle supportvragen. Bedankt voor je geduld!", de:"Wir antworten in der Regel innerhalb von 24–48 Stunden auf alle Anfragen. Danke für deine Geduld!", hi:"हम आमतौर पर सभी सहायता अनुरोधों का जवाब 24–48 घंटों में देते हैं। धैर्य के लिए धन्यवाद!", bn:"আমরা সাধারণত সব সহায়তা অনুরোধের উত্তর ২৪–৪৮ ঘণ্টার মধ্যে দিই। ধৈর্যের জন্য ধন্যবাদ!", id:"Kami biasanya menjawab semua permintaan dukungan dalam 24–48 jam. Terima kasih atas kesabaran Anda!", ur:"ہم عام طور پر تمام سپورٹ درخواستوں کا جواب 24–48 گھنٹوں میں دیتے ہیں۔ آپ کے صبر کا شکریہ!", tr:"Genellikle tüm destek taleplerini 24–48 saat içinde yanıtlıyoruz. Sabrın için teşekkürler!", it:"Di norma rispondiamo a tutte le richieste entro 24–48 ore. Grazie per la pazienza!", ja:"すべてのお問い合わせに通常24〜48時間以内に返信しています。お待ちいただきありがとうございます。", ko:"모든 문의에 보통 24~48시간 안에 답변드립니다. 기다려 주셔서 감사합니다!", ru:"Обычно мы отвечаем на все обращения в течение 24–48 часов. Спасибо за терпение!" },
    "sup.pageTitle": { en:"Support — Magic Domino™", es:"Soporte — Magic Domino™", fr:"Assistance — Magic Domino™", pt:"Suporte — Magic Domino™", ar:"الدعم — Magic Domino™", zh:"支持 — Magic Domino™", nl:"Support — Magic Domino™", de:"Hilfe — Magic Domino™", hi:"सहायता — Magic Domino™", bn:"সহায়তা — Magic Domino™", id:"Dukungan — Magic Domino™", ur:"سپورٹ — Magic Domino™", tr:"Destek — Magic Domino™", it:"Assistenza — Magic Domino™", ja:"サポート — Magic Domino™", ko:"지원 — Magic Domino™", ru:"Поддержка — Magic Domino™" },

